/// <summary>
/// CB501_ISP_Security
/// </summary>
[ExtensionOf(formStr(PurchCreateOrder))]
final class METPurchCreateOrderFrm_Extension
{
    private boolean isISPUser;
    
}

Method.Source:
/// <summary>
/// For ISP users creating manual POs, default the buyer group to one they have access to oterwise they won't be able to see the created POs
/// Needs to be done after the OrderAccount\modified as it is bringing the buyer code against the vendor
/// </summary>
void orderAccountModified()
{        
    if (isISPUser)
    {
        PurchTable purchTable = this.dataSource(formDataSourceStr(PurchCreateOrder, PurchTable)).cursor();
        purchTable.ItemBuyerGroupId = (select firstonly ItemBuyerGroupId from METBuyerGroupUnionView where METBuyerGroupUnionView.User == curUserId() ).ItemBuyerGroupId;
    }
    
    next orderAccountModified();        
}

    /// <summary>
    /// Making item buyer group mandatory for ISP users
    /// </summary>
    void init()
    {
        next init();

        isISPUser = METisISPUser();

        if (isISPUser)
        {
            FormDataSource PurchTable_ds = this.dataSource(formDataSourceStr(PurchCreateOrder, PurchTable));
            PurchTable_ds.object(fieldNum(PurchTable, ItemBuyerGroupId)).allowEdit(false);
        }
    }

    void modifyForm()
    {
        next modifyForm();
        
        // Security policy for Warehouse
        if (METSecurityPolicyHelper::isRoleActiveForCurrentUser(roleStr(METInventLocationPolicyRole)))
        {
            container siteAndWarehouseCon = METUserSecurityWarehouseList::findSingleSiteAndWarehouseByUser();

            if (conLen(siteAndWarehouseCon) > 0)
            {
                // Set Site field and lock it
                PurchTable.InventSiteId = conPeek(siteAndWarehouseCon, 1);
                PurchTable.modifiedField(fieldNum(PurchTable, InventSiteId));
                PurchTable_ds.object(fieldNum(PurchTable, InventSiteId)).allowEdit(false);

                // Set Warehouse field and lock it
                PurchTable.InventLocationId = conPeek(siteAndWarehouseCon, 2);
                PurchTable.modifiedField(fieldNum(PurchTable, InventLocationId));
                PurchTable_ds.object(fieldNum(PurchTable, InventLocationId)).allowEdit(false);
            }
        }
    }
